import { Flow, FlowObject, wfa, trigger, action } from '@servicenow/sdk/automation'
import { StringColumn, IntegerColumn, BooleanColumn } from '@servicenow/sdk/core'

/**
 * Test case: Complex object WITH explicit $id and co_type_name (non-deterministic, from UI)
 * Expected behavior:
 * 1. Fluent → XML: Use the provided $id and co_type_name
 * 2. XML → Fluent: Should include $id and co_type_name (since they're NOT deterministic)
 */
Flow(
    {
        $id: Now.ID['non_deterministic_complex_object_flow'],
        name: 'Flow with Non-Deterministic Complex Object',
        runAs: 'user',
        flowVariables: {
            customer: FlowObject({
                $id: 'custom_complex_object_id_from_ui',
                co_type_name: 'CustomCustomerType123',
                fields: {
                    firstName: StringColumn({
                        label: 'First Name',
                        mandatory: true,
                    }),
                    lastName: StringColumn({
                        label: 'Last Name',
                        mandatory: true,
                    }),
                    email: StringColumn({
                        label: 'Email Address',
                    }),
                    age: IntegerColumn({
                        label: 'Age',
                    }),
                    isActive: BooleanColumn({
                        label: 'Active Status',
                        default: true,
                    }),
                },
                label: 'Customer',
            }),
        },
    },
    wfa.trigger(
        trigger.record.updated,
        {
            $id: Now.ID['non_deterministic_trigger'],
        },
        {
            table: 'customer_account',
            trigger_strategy: 'once',
        }
    ),
    (_params) => {
        wfa.action(
            action.core.log,
            {
                $id: Now.ID['non_deterministic_log_action'],
            },
            {
                log_level: 'info',
                log_message: wfa.dataPill(_params.flowVariables.customer.firstName, 'string'),
            }
        )
    }
)
